import{z as i,x as N,o as A,c as B,q as r,j as o,D as E,d as n,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"向量数据库与 ANN","description":"","frontmatter":{"title":"向量数据库与 ANN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vector-db-ann.md","filePath":"cs/vector-db-ann.md","lastUpdated":1791063341000}'),d={name:"cs/vector-db-ann.md"};function p(m,a,c,D,u,h){const t=N("Mermaid");return A(),B("div",null,[a[2]||(a[2]=r('<h1 id="向量数据库与-ann" tabindex="-1">向量数据库与 ANN <a class="header-anchor" href="#向量数据库与-ann" aria-label="Permalink to &quot;向量数据库与 ANN&quot;">​</a></h1><div class="epigraph"><p>近邻在高维不走 B+：HNSW、IVF、PQ 用图或聚类近似。过滤、事务与新鲜度仍是数据库问题，ANN 只替换距离索引。</p><footer>—— 据 Malkov and Yashunin HNSW；Jégou 乘积量化；ANN 库实践</footer></div><p><a href="/cs/timeseries-db">上一课</a>的轴是时间。本课轴是高维向量。计算机栏可能有距离与哈希；数据库进阶钉：<strong>ANN 索引 + 行过滤 + 持久</strong>。不是大模型课：不讲训练 Transformer，只讲存查询嵌入。与全文倒排可混合（稀疏+稠密）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 kNN 线性扫或高维树崩。ANN：召回换延迟。HNSW 图、IVF 倒排质心、PQ 压缩距离。缺口是数据库合同：插入删除如何维护图、事务可见性、与 SQL <code>WHERE</code> 先过滤还是先 ANN（pre/post filtering）改变召回。分片：向量切不好，常复制索引或按业务键切。</p><p>WAL：向量大，日志放大；常外置文件+行存 id。BLOB 课的引用模型。</p><p><span class="marginnote">术语翻译：ANN 就是用「只在图上或聚类桶里探一小部分候选」的手段来做「从百万向量里找最像的 k 条」的事——它承认可能漏掉真正的第一名，换来几十到几百倍的加速。</span></p><p><span class="marginnote">Malkov and Yashunin 的 HNSW；Jégou 等的乘积量化。过滤与召回的权衡是产品核心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行：id、向量、元数据。索引：ANN 结构可重建。查询：先元数据 zone/B+ 缩小再 ANN，或 ANN 再过滤（可能不够 k 条）。CDC 更新向量要重建邻接，延迟高。</p><p>与学习索引：都是近似结构+纠正；ANN 纠正是探更多邻居，不是二分键。</p><p><span class="marginnote">数字实例：库里 1000 万条向量，若 WHERE 条件只留下 100 条有权限的结果，先 ANN 再过滤——ANN 取回的 top 100 里可能一条都过不了滤；先过滤再 ANN 才能在小集合上查。召回 0.9 的含义：真的近邻里平均 10 条能找对 9 条，不是「返回结果 90% 正确」。</span></p>',12)),(A(),o(l,null,{default:E(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20QV%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20ANN%5B%22HNSW%20%2F%20IVF%22%5D%0A%20%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20PRE%5B%22%E5%85%88%E8%BF%87%E6%BB%A4%E6%88%96%E5%90%8E%E8%BF%87%E6%BB%A4%22%5D%0A%20%20ANN%20--%3E%20IDS%5B%22%E5%80%99%E9%80%89%20id%22%5D%0A%20%20IDS%20--%3E%20HEAP%5B%22%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"MVCC：新向量版本对旧快照不可见，ANN 图若无版本会泄漏——只读重建或按段（LSM 式不可变 ANN 段）。RTO：重建索引时间可超预算，要备副本。",-1)),a[5]||(a[5]=e("p",null,"校准：代价不是页 I/O 公式，是距离计算次数。优化器常把 ANN 当黑盒选择率=k。",-1)),(A(),o(l,null,{default:E(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E5%85%A5%E6%96%B0%E5%90%91%E9%87%8F%E7%89%88%E6%9C%AC%22%5D%20--%3E%20SEG%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%E8%BF%9B%E4%B8%8D%E5%8F%AF%E5%8F%98%E6%AE%B5%22%5D%0A%20%20SEG%20--%3E%20IDX%5B%22%E6%AE%B5%E5%86%85%20ANN%20%E5%9B%BE%E7%8B%AC%E7%AB%8B%E5%BB%BA%22%5D%0A%20%20IDX%20--%3E%20MERGE%5B%22%E5%90%8E%E5%8F%B0%E5%90%88%E5%B9%B6%E9%87%8D%E5%BB%BA%E9%82%BB%E6%8E%A5%22%5D%0A%20%20OLD%5B%22%E6%97%A7%E6%AE%B5%3A%20%E6%97%A7%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20Q%7B%22%E6%9F%A5%E8%AF%A2%E6%8C%89%20MVCC%20%E8%AF%BB%E5%93%AA%E6%AE%B5%3F%22%7D%0A%20%20MERGE%20--%3E%20Q%0A%20%20Q%20--%20%22%E6%97%A7%E4%BA%8B%E5%8A%A1%22%20--%3E%20OLD%0A%20%20Q%20--%20%22%E6%96%B0%E4%BA%8B%E5%8A%A1%22%20--%3E%20NEWSEG%5B%22%E6%96%B0%E6%AE%B5%E5%8F%AF%E8%A7%81%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">为什么重要：直接在活图上改邻接边，并发读会看到半更新的图——邻居指针指向还没建好的地方，召回突然掉到不可复现的水平。按段不可变再后台合并，把「改图」变成「换段」，读路径永远是完整的图。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Lucene 倒排实现——下一课搜索引擎。也不把向量检索当「语义 SQL 自动」。量化栏不出现。</p><p>后课默认：kNN 走 ANN，谓词策略要测召回。全文检索引擎：词项倒排+打分，可与向量混合检索。</p><p>没有元数据过滤合同的 ANN 会在权限与租户上错召回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ANN 用图/聚类近似 kNN；过滤顺序影响召回。</li><li>持久、MVCC、分片仍是库问题。</li><li>全文检索引擎下一课。</li><li>出处：HNSW；PQ；倒排课对照。</li></ul>',7))])}const S=i(d,[["render",p]]);export{F as __pageData,S as default};
